198	     1	//! Raw blob hashing and the product H preimage; neither implies admission.
199	     2	use crate::canonical::{self, Value};
200	     3	use alloc::{string::String, vec::Vec};
201	     4	use core::fmt::{self, Write};
202	     5	use sha2_const_stable::Sha256;
203	     6	
204	     7	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
205	     8	pub enum Error {
206	     9	    Domain,
207	    10	    Canonical(canonical::Error),
208	    11	}
209	    12	
210	    13	impl fmt::Display for Error {
211	    14	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
212	    15	        match self {
213	    16	            Self::Domain => f.write_str("invalid hash domain"),
214	    17	            Self::Canonical(error) => write!(f, "canonical encoding failed: {error}"),
215	    18	        }
216	    19	    }
217	    20	}
218	    21	
219	    22	impl core::error::Error for Error {
220	    23	    fn source(&self) -> Option<&(dyn core::error::Error + 'static)> {
221	    24	        match self {
222	    25	            Self::Canonical(error) => Some(error),
223	    26	            Self::Domain => None,
224	    27	        }
225	    28	    }
226	    29	}
227	    30	
228	    31	pub fn raw_sha256(bytes: &[u8]) -> [u8; 32] {
229	    32	    Sha256::new().update(bytes).finalize()
230	    33	}
231	    34	
232	    35	pub fn hex(digest: &[u8; 32]) -> String {
233	    36	    let mut value = String::with_capacity(64);
234	    37	    for byte in digest {
235	    38	        write!(value, "{byte:02x}").expect("writing to String cannot fail");
236	    39	    }
237	    40	    value
238	    41	}
239	    42	
240	    43	/// Complete H preimage. Callers must separately admit the registered descriptor.
241	    44	pub fn frame(domain: &str, value: &Value) -> Result<Vec<u8>, Error> {
242	    45	    if domain.is_empty()
243	    46	        || !domain
244	    47	            .bytes()
245	    48	            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || matches!(b, b'-' | b'.'))
246	    49	    {
247	    50	        return Err(Error::Domain);
248	    51	    }
249	    52	    let canonical = canonical::encode(value).map_err(Error::Canonical)?;
250	    53	    let mut frame = Vec::new();
251	    54	    frame.extend_from_slice(b"opensip.product.v1\0");
252	    55	    frame.extend_from_slice(domain.as_bytes());
253	    56	    frame.push(0);
254	    57	    frame.extend_from_slice(&(canonical.len() as u64).to_be_bytes());
255	    58	    frame.extend_from_slice(&canonical);
256	    59	    Ok(frame)
257	    60	}
258	    61	
259	    62	pub fn identity(domain: &str, value: &Value) -> Result<[u8; 32], Error> {
260	    63	    Ok(raw_sha256(&frame(domain, value)?))
261	    64	}
