493	   156	fn digest(value: &JsonValue) -> Result<[u8; 32], AssetError> {
494	   157	    let s = text(value)?.as_bytes();
495	   158	    if s.len() != 64
496	   159	        || !s
497	   160	            .iter()
498	   161	            .all(|x| x.is_ascii_digit() || (b'a'..=b'f').contains(x))
499	   162	    {
500	   163	        return Err(AssetError::Shape);
501	   164	    }
502	   165	    let digit = |v: u8| if v <= b'9' { v - b'0' } else { v - b'a' + 10 };
503	   166	    Ok(std::array::from_fn(|i| {
504	   167	        digit(s[i * 2]) * 16 + digit(s[i * 2 + 1])
505	   168	    }))
506	   169	}
