508	   171	/// Reads at most expected + 1 bytes even from a growing file. Allocation grows
509	   172	/// only with bytes actually supplied; declared lengths never reserve huge memory.
510	   173	fn checked_read(
511	   174	    mut reader: impl Read,
512	   175	    expected: u64,
513	   176	    sha256: &[u8; 32],
514	   177	) -> Result<Vec<u8>, AssetError> {
515	   178	    if expected > MAX_LENGTH {
516	   179	        return Err(AssetError::Length);
517	   180	    }
518	   181	    let mut left = expected + 1;
519	   182	    let mut data = Vec::new();
520	   183	    let mut buffer = [0; 16 * 1024];
521	   184	    while left > 0 {
522	   185	        let cap = left.min(buffer.len() as u64) as usize;
523	   186	        let count = match reader.read(&mut buffer[..cap]) {
524	   187	            Ok(n) => n,
525	   188	            Err(e) if e.kind() == io::ErrorKind::Interrupted => continue,
526	   189	            Err(_) => return Err(AssetError::Io),
527	   190	        };
528	   191	        if count == 0 {
529	   192	            break;
530	   193	        }
531	   194	        if count > cap {
532	   195	            return Err(AssetError::Io);
533	   196	        }
534	   197	        data.try_reserve(count)
535	   198	            .map_err(|_| AssetError::Allocation)?;
536	   199	        data.extend_from_slice(&buffer[..count]);
537	   200	        left -= count as u64;
538	   201	    }
539	   202	    if data.len() as u64 != expected {
540	   203	        return Err(AssetError::Length);
541	   204	    }
542	   205	    if raw_sha256(&data) != *sha256 {
543	   206	        return Err(AssetError::Digest);
544	   207	    }
545	   208	    Ok(data)
546	   209	}
