548	   211	fn manifest(
549	   212	    raw: &[u8],
550	   213	    pin: &FixturePin,
551	   214	    projection: &[u8; 32],
552	   215	) -> Result<Vec<Member>, AssetError> {
553	   216	    let value = parse_json(raw).map_err(|_| AssetError::Shape)?;
554	   217	    let doc = object(
555	   218	        &value,
556	   219	        &["schemaVersion", "projectionSchemaSha256s", "assets"],
557	   220	    )?;
558	   221	    if length(&doc["schemaVersion"])? != 1 {
559	   222	        return Err(AssetError::Shape);
560	   223	    }
561	   224	    let schemas = array(&doc["projectionSchemaSha256s"])?;
562	   225	    if schemas.is_empty() {
563	   226	        return Err(AssetError::Shape);
564	   227	    }
565	   228	    let mut previous = None;
566	   229	    let mut compatible = false;
567	   230	    for item in schemas {
568	   231	        let current = digest(item)?;
569	   232	        if previous.is_some_and(|p| p >= current) {
570	   233	            return Err(AssetError::Order);
571	   234	        }
572	   235	        compatible |= current == *projection;
573	   236	        previous = Some(current);
574	   237	    }
575	   238	    if !compatible {
576	   239	        return Err(AssetError::Incompatible);
577	   240	    }
578	   241	    let rows = array(&doc["assets"])?;
579	   242	    if rows.is_empty() {
580	   243	        return Err(AssetError::Shape);
581	   244	    }
582	   245	    let mut members: Vec<Member> = Vec::new();
583	   246	    for row in rows {
584	   247	        let fields = object(row, &["path", "sha256", "bytes", "role"])?;
585	   248	        let path = text(&fields["path"])?;
586	   249	        if !canonical_path(path) || !under(path, &pin.root) {
587	   250	            return Err(AssetError::Path);
588	   251	        }
589	   252	        if path == pin.manifest_path {
590	   253	            return Err(AssetError::SelfListed);
591	   254	        }
592	   255	        if members
593	   256	            .last()
594	   257	            .is_some_and(|old| old.path.as_bytes() >= path.as_bytes())
595	   258	        {
596	   259	            return Err(AssetError::Order);
597	   260	        }
598	   261	        let role = match text(&fields["role"])? {
599	   262	            "script" => Role::Script,
600	   263	            "style" => Role::Style,
601	   264	            "font" => Role::Font,
602	   265	            "image" => Role::Image,
603	   266	            "notice" => Role::Notice,
604	   267	            _ => return Err(AssetError::Shape),
605	   268	        };
606	   269	        members.push(Member {
607	   270	            path: path.into(),
608	   271	            sha256: digest(&fields["sha256"])?,
609	   272	            bytes: length(&fields["bytes"])?,
610	   273	            role,
611	   274	        });
612	   275	    }
613	   276	    Ok(members)
614	   277	}
