616	   279	/// Development algorithm trial entry point. Product integration must replace
617	   280	/// FixturePin with a private compiled constant and the projection with the
618	   281	/// selected renderer's compiled schema digest. This function is NOT that API.
619	   282	pub fn verify_fixture_assets(
620	   283	    source: &mut impl AssetSource,
621	   284	    pin: &FixturePin,
622	   285	    projection: &[u8; 32],
623	   286	) -> Result<VerifiedBundle, AssetError> {
624	   287	    if !canonical_path(&pin.root)
625	   288	        || !canonical_path(&pin.manifest_path)
626	   289	        || !under(&pin.manifest_path, &pin.root)
627	   290	    {
628	   291	        return Err(AssetError::Path);
629	   292	    }
630	   293	    // The current exact-JSON parser has a 4 MiB profile. This is a declared trial
631	   294	    // limit, checked before opening; final build must prove its actual manifest
632	   295	    // fits or select a separately reviewed bounded private-manifest profile.
633	   296	    if pin.manifest_bytes == 0 || pin.manifest_bytes > opensip_identity::MAX_BYTES as u64 {
634	   297	        return Err(AssetError::Length);
635	   298	    }
636	   299	    let raw = checked_read(
637	   300	        source
638	   301	            .open_regular(&pin.manifest_path)
639	   302	            .map_err(|_| AssetError::Io)?,
640	   303	        pin.manifest_bytes,
641	   304	        &pin.manifest_sha256,
642	   305	    )?;
643	   306	    let members = manifest(&raw, pin, projection)?;
644	   307	    let mut verified = Vec::new();
645	   308	    for member in members {
646	   309	        let bytes = checked_read(
647	   310	            source
648	   311	                .open_regular(&member.path)
649	   312	                .map_err(|_| AssetError::Io)?,
650	   313	            member.bytes,
651	   314	            &member.sha256,
652	   315	        )?;
653	   316	        verified.push(VerifiedAsset {
654	   317	            path: member.path,
655	   318	            role: member.role,
656	   319	            bytes,
657	   320	        });
658	   321	    }
659	   322	    // No partial verified collection is returned on any failure.
660	   323	    Ok(VerifiedBundle {
661	   324	        root: pin.root.clone(),
662	   325	        manifest_path: pin.manifest_path.clone(),
663	   326	        manifest_sha256: pin.manifest_sha256,
664	   327	        assets: verified,
665	   328	    })
666	   329	}
