670	   333	/// completeness and the exact single manifest exclusion.
671	   334	pub fn fixture_completeness(
672	   335	    verified: &VerifiedBundle,
673	   336	    regular_paths: &[String],
674	   337	) -> Result<(), AssetError> {
675	   338	    let mut expected: Vec<_> = verified.assets.iter().map(|a| a.path.as_str()).collect();
